import Foundation
import FirebaseFirestore
import MapKit

/// Represents a trip created by a user.
/// - Parameters:
///   - id: The unique string identifier for the trip, generated by Firebase.
///   - ownerId: The identifier of the user who created the trip.
///   - name: The name of the trip.
///   - places: An array of MapKit place identifiers representing the stops included in the trip, in order.
///   - createdAt: The date and time when the trip was created.
///   - preferences: An array of preferences representing the trip's selected categories or themes.
struct Trip: Identifiable {
    
    var id: String
    let ownerId: String
    let ownerUsername: String
    let name: String
    let description: String
    let places: [String]
    let createdAt: Date
    let preferences: [String]
    
    var savedByUser: Bool = false
    var mkMapItemPlaces: [MapItem] = []
    
    init(id: String = "", ownerUsername:String, ownerId: String, name: String, description: String, places: [String], createdAt: Date = Date(), preferences: [String], savedByUser: Bool = false) {
        self.id = id
        self.ownerId = ownerId
        self.ownerUsername = ownerUsername
        self.name = name
        self.description = description
        self.places = places
        self.createdAt = createdAt
        self.preferences = preferences
        self.savedByUser = savedByUser
        
    }
    
    
    var asDictionary: [String: Any] {
        
        return [
            "id": id,
            "ownerId": ownerId,
            "ownerUsername": ownerUsername,
            "name": name,
            "description": description,
            "places": places,
            "createdAt" : createdAt,
            "preferences" : preferences
        ]
    }
    
    /// Converts a Firestore document back into Trip.
    init?(snapshot: QueryDocumentSnapshot, isSaved: Bool) {
        
        let data = snapshot.data()
        
        guard
            let ownerId = data["ownerId"] as? String,
            let ownerUsername = data["ownerUsername"] as? String,
            let name = data["name"] as? String,
            let description = data["description"] as? String,
            let places = data["places"] as? [String],
            let preferences = data["preferences"] as? [String],
            let timestamp = data["createdAt"] as? Timestamp
                
        else {
            return nil
        }
        
        id = snapshot.documentID
        self.ownerId = ownerId
        self.ownerUsername = ownerUsername
        self.name = name
        self.description = description
        self.places = places
        self.preferences = preferences
        self.savedByUser = isSaved
        createdAt = timestamp.dateValue()
    }
    
}
